  ('pri-math-051', 1, 'in_review', array['primary']::text[], 'mathematics', 'Multiplication', 'Times tables', 1, 'remember', 'numeric', 'What is 9 × 8?', null, null, 'Recall multiplication facts.', 'Primary mathematics: multiplication facts (e.g. KSSR Matematik Tahun 3).', '{"system":"KSSR","subject":"Matematik","years":[3]}'::jsonb, 'Eduventure (original questions)', 'CC BY 4.0'),
