  ('usec-amath-012', 1, 'in_review', array['upper_secondary']::text[], 'additional_mathematics', 'Logarithms', 'Laws of logarithms', 2, 'evaluate', 'true_false', 'True or false: log(a + b) = log a + log b.', null, null, 'Apply the laws of logarithms correctly.', 'Upper secondary additional mathematics: indices and logarithms (e.g. KSSM Matematik Tambahan Tingkatan 4 / SPM).', '{"system":"KSSM","subject":"Matematik Tambahan","years":[4]}'::jsonb, 'Eduventure (original questions)', 'CC BY 4.0'),
  ('usec-amath-013', 1, 'in_review', array['upper_secondary']::text[], 'additional_mathematics', 'Vectors', 'Magnitude', 2, 'apply', 'numeric', 'Find the magnitude of the vector 6i + 8j.', null, null, 'Calculate the magnitude of a vector.', 'Upper secondary additional mathematics: vectors (e.g. KSSM Matematik Tambahan Tingkatan 4 / SPM).', '{"system":"KSSM","subject":"Matematik Tambahan","years":[4]}'::jsonb, 'Eduventure (original questions)', 'CC BY 4.0'),
  ('usec-bio-014', 1, 'in_review', array['upper_secondary']::text[], 'biology', 'Plants', 'Gas exchange', 1, 'remember', 'mcq', 'Through which openings do gases mainly enter and leave a leaf?', '[{"id":"a","text":"Stomata"},{"id":"b","text":"Xylem"},{"id":"c","text":"Phloem"},{"id":"d","text":"Cuticle"}]'::jsonb, null, 'Describe gas exchange in plants.', 'Upper secondary biology: plant organs (e.g. KSSM Biologi Tingkatan 4 / SPM).', '{"system":"KSSM","subject":"Biologi","years":[4]}'::jsonb, 'Eduventure (original questions)', 'CC BY 4.0'),
  ('usec-bio-015', 1, 'in_review', array['upper_secondary']::text[], 'biology', 'Human organs', 'The liver', 3, 'understand', 'multi_select', 'Select all the functions of the liver.', '[{"id":"a","text":"Producing bile"},{"id":"b","text":"Storing glycogen"},{"id":"c","text":"Pumping blood"},{"id":"d","text":"Breaking down toxins"},{"id":"e","text":"Producing insulin"}]'::jsonb, null, 'Describe the functions of the liver.', 'Upper secondary biology: homeostasis and organs (e.g. KSSM Biologi / SPM).', '{"system":"KSSM","subject":"Biologi","years":[4,5]}'::jsonb, 'Eduventure (original questions)', 'CC BY 4.0'),
