  ('usec-bio-017', 1, 'in_review', array['upper_secondary']::text[], 'biology', 'Transport in plants', 'Plant tissues', 2, 'understand', 'matching', 'Match each plant structure to its job.', '{"left":[{"id":"a","text":"Xylem"},{"id":"b","text":"Phloem"},{"id":"c","text":"Root hair cell"}],"right":[{"id":"x","text":"Absorbs water from the soil"},{"id":"y","text":"Carries water and minerals up the plant"},{"id":"z","text":"Carries sugars around the plant"}]}'::jsonb, null, 'Describe transport in plants.', 'Upper secondary biology: transport in plants (e.g. KSSM Biologi Tingkatan 4 / SPM).', '{"system":"KSSM","subject":"Biologi","years":[4]}'::jsonb, 'Eduventure (original questions)', 'CC BY 4.0'),
