insert into public.question_keys (question_id, answer, explanation, wrong, mistakes) values
  ('pri-math-051', '{"value":72,"tolerance":0}'::jsonb, '9 × 8 = 72. Trick: 10 × 8 = 80, then take away one 8: 80 − 8 = 72.', null, '[{"value":63,"why":"63 is 9 × 7, one group of 9 too few."},{"value":81,"why":"81 is 9 × 9."}]'::jsonb),
  ('pri-math-052', '"a"'::jsonb, 'Multiply the top and bottom of 1/2 by 4: 4/8. Four of eight equal parts is the same as one of two.', '{"b":"2/3 is more than a half.","c":"3/4 is more than a half.","d":"1/4 is half of a half."}'::jsonb, null),
  ('pri-math-053', '{"value":30,"tolerance":0}'::jsonb, '1,000 is 10 hundreds, so 3,000 is 30 hundreds (30 × 100 = 3,000).', null, '[{"value":3,"why":"3 is the number of thousands; each thousand holds 10 hundreds."}]'::jsonb),
  ('pri-math-054', '["b","d","a","c"]'::jsonb, 'All have 2 thousands, so compare the hundreds: 0, 0, 1, 9. For the two with 0 hundreds, compare the tens: 2,019 < 2,091.', null, null),
  ('pri-math-055', '["a","c","e"]'::jsonb, 'Even numbers end in 0, 2, 4, 6 or 8 and can be split into two equal groups.', '{"b":"21 ends in 1, so it is odd.","d":"47 ends in 7, so it is odd."}'::jsonb, null),
  ('pri-math-056', '{"value":21,"tolerance":0,"unit":"m²"}'::jsonb, 'Area = length × width = 7 × 3 = 21 m².', null, '[{"value":20,"why":"20 m is the perimeter; area multiplies length by width."},{"value":10,"why":"Area multiplies the sides; it does not add them."}]'::jsonb),
  ('pri-math-057', '"true"'::jsonb, '"Kilo" means one thousand, so 1 kilogram = 1,000 grams.', '{"false":"\"Kilo\" always means 1,000: 1 kilogram = 1,000 grams, 1 kilometre = 1,000 metres."}'::jsonb, null),
  ('pri-math-058', '{"value":84,"tolerance":0}'::jsonb, '7 boxes of 12 eggs: 7 × 12 = 84. (7 × 10 = 70 and 7 × 2 = 14; 70 + 14 = 84.)', null, '[{"value":19,"why":"19 adds the numbers; 7 boxes of 12 means multiply."}]'::jsonb),
  ('pri-math-059', '"a"'::jsonb, '15 = 3 × 5, so it is in both the 3 times table and the 5 times table.', '{"b":"10 is a multiple of 5, but not of 3.","c":"9 is a multiple of 3, but not of 5.","d":"8 is a multiple of neither 3 nor 5."}'::jsonb, null),
  ('pri-math-060', '{"accept":["product","the product"]}'::jsonb, 'Multiplying gives a product (4 × 5: the product is 20). Adding gives a sum.', null, null),
  ('pri-sci-041', '"a"'::jsonb, 'Clear glass lets almost all light through, which is why windows are made of it.', '{"b":"Wood is opaque: no light passes through.","c":"Cardboard is opaque.","d":"Metal is opaque."}'::jsonb, null),
  ('pri-sci-042', '"true"'::jsonb, 'Light travels in straight lines. An opaque object stops the light, leaving a dark area behind it: a shadow.', '{"false":"Shadows are made exactly where an object stops light from reaching a surface."}'::jsonb, null),
  ('pri-sci-043', '["a","c","e"]'::jsonb, 'Mammals feed their babies milk and breathe air with lungs. Whales, bats and monkeys are all mammals.', '{"b":"Sharks are fish: they breathe through gills.","d":"Penguins are birds: they have feathers and lay eggs."}'::jsonb, null),
  ('pri-sci-044', '{"accept":["tadpole","a tadpole"]}'::jsonb, 'A tadpole hatches from a frog''s egg, breathes with gills and swims with its tail before it grows legs.', null, null),
  ('pri-sci-045', '["c","a","b","d"]'::jsonb, 'A seed germinates into a seedling, grows into an adult plant that flowers, and the flowers become fruits with new seeds.', null, null),
  ('pri-eng-031', '"a"'::jsonb, '"Friend" is spelled f-r-i-e-n-d. A memory trick: a friend is there to the end (frI END).', '{"b":"The i and e are swapped: it is fri-end.","c":"There is an i before the e: fri-end.","d":"It ends in d, not t."}'::jsonb, null),
  ('pri-eng-032', '["a","c","e"]'::jsonb, 'Verbs tell us what someone does: run, eat, sleep.', '{"b":"\"Happy\" is an adjective: it describes a feeling.","d":"\"Blue\" is an adjective: it describes a colour."}'::jsonb, null),
  ('pri-eng-033', '"true"'::jsonb, '"Quickly" means at a fast speed and "slowly" means at a low speed, so they are opposites (antonyms).', '{"false":"One means fast and the other means not fast: they are opposites."}'::jsonb, null),
  ('pri-eng-034', '{"a":"y","b":"z","c":"x"}'::jsonb, 'A baby cat is a kitten, a baby dog is a puppy and a baby cow is a calf.', null, null),
  ('pri-eng-035', '{"accept":["feet"]}'::jsonb, '"Foot" has an irregular plural: one foot, two feet (like tooth → teeth).', null, null),
  ('lsec-math-046', '{"value":90,"tolerance":0}'::jsonb, '1/4 of 120 is 30, so 3/4 is 3 × 30 = 90.', null, '[{"value":30,"why":"30 is 1/4; multiply by 3 to get 3/4."},{"value":160,"why":"160 is 120 ÷ 3/4; finding 3/4 of an amount means multiply by 3/4."}]'::jsonb),
  ('lsec-math-047', '"a"'::jsonb, 'Reflecting in the x-axis keeps x the same and changes the sign of y.', '{"b":"(−2, 3) is the reflection in the y-axis.","c":"(−2, −3) is a rotation of 180° about the origin.","d":"(3, 2) is the reflection in the line y = x."}'::jsonb, null),
  ('lsec-math-048', '{"value":360,"tolerance":0,"unit":"°"}'::jsonb, 'A quadrilateral can be split into two triangles: 2 × 180° = 360°.', null, '[{"value":180,"why":"180° is for a triangle; a quadrilateral is two triangles."}]'::jsonb),
  ('lsec-math-049', '["a","c","e"]'::jsonb, 'A prime number has exactly two factors, 1 and itself: 2, 11 and 17. (2 is the only even prime.)', '{"b":"9 = 3 × 3, so it has three factors (1, 3, 9).","d":"15 = 3 × 5."}'::jsonb, null),
  ('lsec-math-050', '"false"'::jsonb, 'On a number line, −5 is further to the left than −2, so −5 is smaller. (A debt of RM5 is worse than a debt of RM2.)', '{"true":"With negatives, the bigger the number after the minus sign, the smaller the value: −5 < −2."}'::jsonb, null),
  ('lsec-sci-034', '"a"'::jsonb, 'Friction acts where surfaces touch and opposes sliding. It lets us walk without slipping and makes brakes work.', '{"b":"Gravity pulls objects towards each other, such as towards the Earth.","c":"Magnetic force acts between magnets and magnetic materials.","d":"Upthrust is the upward push of a liquid or gas on an object."}'::jsonb, null),
  ('lsec-sci-035', '{"value":100,"tolerance":0,"unit":"°C"}'::jsonb, 'Pure water boils at 100 °C at sea level. At high altitude, where pressure is lower, it boils at a lower temperature.', null, '[{"value":0,"why":"0 °C is the freezing (melting) point of water."}]'::jsonb),
  ('lsec-sci-036', '["a","b","c"]'::jsonb, 'Glucose + oxygen → carbon dioxide + water + energy.', '{"d":"Oxygen is used up by respiration, not produced.","e":"Glucose is broken down by respiration, not produced."}'::jsonb, null),
  ('lsec-sci-037', '["b","d","a","c"]'::jsonb, 'Crust → mantle → outer core (liquid metal) → inner core (solid metal).', null, null),
  ('lsec-sci-038', '"true"'::jsonb, 'Acids turn blue litmus red; alkalis turn red litmus blue.', '{"false":"Blue litmus turning red is the standard test for an acid."}'::jsonb, null),
  ('usec-amath-009', '{"value":2,"tolerance":0}'::jsonb, 'f⁻¹(7) is the x that gives f(x) = 7: 2x + 3 = 7, so x = 2.', null, '[{"value":17,"why":"17 is f(7); the inverse asks which input gives 7."}]'::jsonb),
  ('usec-amath-010', '"a"'::jsonb, 'A full turn is 2π radians = 360°, so a half turn, 180°, is π radians.', '{"b":"2π radians is a full turn, 360°.","c":"π/2 radians is a right angle, 90°.","d":"To convert degrees to radians, multiply by π/180, not by π."}'::jsonb, null),
  ('usec-amath-011', '{"value":96,"tolerance":0}'::jsonb, 'a = 3, r = 2. Tₙ = arⁿ⁻¹, so T₆ = 3 × 2⁵ = 3 × 32 = 96.', null, '[{"value":192,"why":"192 is the 7th term; the power is n − 1 = 5, not 6."},{"value":18,"why":"That treats it as adding 3 each time; a GP multiplies by r = 2."}]'::jsonb),
  ('usec-amath-012', '"false"'::jsonb, 'The law is log(ab) = log a + log b: the log of a product, not a sum. For example, log(1 + 1) = log 2, but log 1 + log 1 = 0.', '{"true":"Logs turn multiplication into addition: log(a × b) = log a + log b. There is no simple rule for log(a + b)."}'::jsonb, null),
  ('usec-amath-013', '{"value":10,"tolerance":0}'::jsonb, '|6i + 8j| = √(6² + 8²) = √(36 + 64) = √100 = 10.', null, '[{"value":14,"why":"14 adds the components; use Pythagoras: √(6² + 8²)."},{"value":100,"why":"100 is the magnitude squared; take the square root."}]'::jsonb),
  ('usec-bio-014', '"a"'::jsonb, 'Stomata are tiny pores, mostly on the underside of leaves, opened and closed by guard cells.', '{"b":"Xylem carries water and minerals.","c":"Phloem carries sugars.","d":"The cuticle is a waxy layer that reduces water loss; gases do not pass through it easily."}'::jsonb, null),
  ('usec-bio-015', '["a","b","d"]'::jsonb, 'The liver makes bile, stores glucose as glycogen and detoxifies harmful substances such as alcohol.', '{"c":"The heart pumps blood.","e":"Insulin is made by the pancreas."}'::jsonb, null),
  ('usec-bio-016', '{"value":4,"tolerance":0}'::jsonb, 'Two atria (upper chambers) and two ventricles (lower chambers).', null, '[{"value":2,"why":"There are two sides, each with two chambers: an atrium and a ventricle."}]'::jsonb),
  ('usec-bio-017', '{"a":"y","b":"z","c":"x"}'::jsonb, 'Root hair cells absorb water, xylem carries it upwards, and phloem moves sugars made in the leaves to where they are needed.', null, null),
  ('usec-bio-018', '"true"'::jsonb, 'A vaccine exposes the immune system to a harmless form of an antigen, so it makes antibodies and memory cells and can respond quickly to the real pathogen later.', '{"false":"That is how vaccines work: they train the immune system using antigens without causing the disease."}'::jsonb, null)
